urlset:
{{ base_url }}/
{%- if products %}
{{ base_url }}/products
{%- for product in products %}
{{ base_url }}/products/{{ product.id }}
{%- endfor %}
{%- endif %}
{%- if all_news %}
{{ base_url }}/news
{%- for news in all_news %}

  {{ base_url }}/news/{{ news.id }}
  {%- if news.date_of_the_news %}
  {{ news.date_of_the_news.isoformat() }}
  {%- endif %}

{%- endfor %}
{%- endif %}
{%- for path in text_pages %}
{{ base_url }}{{ path }}
{%- endfor %}
